<?php declare(strict_types=1); $platform = $view->boolean('platform'); ?>
<section data-qmdb-fragment-root><ul><?php foreach ($view->list('events') as $event): ?><?php if (is_array($event)): ?><li><strong><?= $escape->escapeText((string)($event['event_code'] ?? '')) ?></strong> — <?= $escape->escapeText((string)($event['occurred_at'] ?? '')) ?> — <?= $escape->escapeText((string)($event['outcome'] ?? '')) ?><?php if ($platform): ?> <a href="/platform/security/events/<?= $escape->escapeAttribute((string)($event['public_id'] ?? '')) ?>"><?= $escape->escapeText($translator->trans('security_audit.detail')) ?></a><?php endif; ?></li><?php endif; ?><?php endforeach; ?></ul><?php if ($view->string('next_cursor') !== ''): ?><a class="button" href="?cursor=<?= $escape->escapeAttribute($view->string('next_cursor')) ?>"><?= $escape->escapeText($translator->trans('security_audit.next')) ?></a><?php endif; ?></section>
